package dev.timeslay.day.reminders

import android.app.Activity
import android.content.Intent
import android.content.pm.PackageManager
import android.net.Uri
import android.os.Build
import android.os.Bundle
import android.provider.Settings

/**
 * Asks for permission to post notifications, which Android 13 and later
 * require. The Dioxus activity is generated by `dx`, so this invisible one
 * makes the request on its behalf and closes again.
 */
class PermissionActivity : Activity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU &&
            checkSelfPermission(PERMISSION) != PackageManager.PERMISSION_GRANTED
        ) {
            requestPermissions(arrayOf(PERMISSION), REQUEST)
        } else {
            // Already allowed by the system, so the user switched them off by
            // hand: only the app's notification settings can turn them back on.
            if (!getSystemService(android.app.NotificationManager::class.java)
                    .areNotificationsEnabled()
            ) {
                openSettings()
            }
            done()
        }
    }

    override fun onRequestPermissionsResult(
        requestCode: Int,
        permissions: Array<out String>,
        grantResults: IntArray,
    ) {
        super.onRequestPermissionsResult(requestCode, permissions, grantResults)
        done()
    }

    private fun openSettings() {
        val intent = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS)
                .putExtra(Settings.EXTRA_APP_PACKAGE, packageName)
        } else {
            Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS)
                .setData(Uri.fromParts("package", packageName, null))
        }
        runCatching { startActivity(intent) }
    }

    /** Refreshes what the settings sheet shows, then closes. */
    private fun done() {
        Thread { runCatching { Reminders.writeDeviceInfo(applicationContext) } }.start()
        finish()
    }

    private companion object {
        const val PERMISSION = "android.permission.POST_NOTIFICATIONS"
        const val REQUEST = 1
    }
}
